async function seed() {
  console.log('🚀 Starting seed...');

  // Insert cars
  const { error: carsError } = await supabase.from('cars').upsert(cars);
  if (carsError) { console.error('❌ Cars insert failed:', carsError.message); return; }
  console.log(`✅ Inserted ${cars.length} cars`);

  // Insert specs
  const specsRows = Object.entries(specs).flatMap(([carId, rows]) =>
    rows.map(r => ({ car_id: Number(carId), label: r.label, value: r.value }))
  );
  const { error: specsError } = await supabase.from('car_specs').upsert(specsRows);
  if (specsError) { console.error('❌ Specs insert failed:', specsError.message); return; }
  console.log(`✅ Inserted ${specsRows.length} spec rows`);

  // Insert features
  const featureRows = Object.entries(features).flatMap(([carId, list]) =>
    list.map(f => ({ car_id: Number(carId), feature: f }))
  );
  const { error: featuresError } = await supabase.from('car_features').upsert(featureRows);
  if (featuresError) { console.error('❌ Features insert failed:', featuresError.message); return; }
  console.log(`✅ Inserted ${featureRows.length} feature rows`);

  // Insert AI valuations
  const valuationRows = Object.entries(aiValuations).map(([carId, v]) => ({
    car_id: Number(carId), ...v
  }));
  const { error: valError } = await supabase.from('ai_valuation').upsert(valuationRows);
  if (valError) { console.error('❌ Valuation insert failed:', valError.message); return; }
  console.log(`✅ Inserted ${valuationRows.length} AI valuation rows`);

  console.log('\n🎉 Seed complete! All 92 cars are now in Supabase.');
}

seed();
